#!/bin/sh
# Rebuilds strip.js from strip-entry.js. The toolchain is pinned by package.json and package-lock.json.
# Usage: sh build.sh   (needs Node.js 20+ and npm; writes strip.js next to this script).
set -eu
here=$(cd "$(dirname "$0")" && pwd)
work=$(mktemp -d)
trap 'rm -rf "$work"' EXIT
cp "$here/package.json" "$here/package-lock.json" "$here/strip-entry.js" "$work/"
cd "$work"
npm ci --ignore-scripts --no-audit --no-fund >/dev/null
./node_modules/.bin/esbuild strip-entry.js --bundle --format=iife --platform=browser --target=es2020 \
  --minify --legal-comments=none --outfile=bundle.js
{
  echo "/* Vendored TypeScript type-stripper for runtime: typescript (see LICENSE.txt and README.md in this folder)."
  echo " * Generated by build.sh from strip-entry.js with esbuild 0.25.12, --bundle --format=iife --platform=browser --target=es2020 --minify --legal-comments=none."
  echo " * Do not edit by hand. */"
  cat bundle.js
} > "$here/strip.js"
